export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const MAIN_ITEMS: Record<string, { value: number; premium: number }> = {
  sword: { value: 1000, premium: 100 },
  amulet: { value: 600, premium: 60 },
  staff: { value: 800, premium: 80 },
  potion: { value: 400, premium: 40 },
};

export class UnknownItemTypeError extends Error {
  constructor(type: string) {
    super(`Unknown item type: ${type}`);
  }
}

function basePremiumOf(item: Item): number {
  const main = MAIN_ITEMS[item.type];
  if (!main) throw new UnknownItemTypeError(item.type);
  return main.premium;
}

export function quotePremium(
  items: Item[],
  _customer: Customer,
  _previousContracts: number,
): number {
  let premium = 0;
  for (const item of items) {
    const base = basePremiumOf(item);
    premium += base + base * FIRST_INSURANCE_SURCHARGE;
  }
  return premium + PROCESSING_FEE;
}
EOF
