import { type Item } from './premium';

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  items: Item[];
  insuranceSum: number;
  remainingCap: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;

function reimbursementFor(_item: Item, amount: number): number {
  return Math.max(0, amount - DEDUCTIBLE);
}

export function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  let payout = 0;
  for (const damage of incident.damages) {
    const item = policy.items.find((candidate) => candidate.type === damage.itemType)!;
    payout += reimbursementFor(item, damage.amount);
  }
  return { payout: Math.floor(payout), remainingCap: policy.remainingCap - payout };
}
EOF
